import subprocess,json,pathlib,collections
data=json.loads((pathlib.Path(__file__).resolve().parent/'nigeria_ocha_lga.json').read_text());expected=collections.Counter(x['state'] for x in data)
script='''import asyncio,asyncpg,os,json\nasync def main():\n p="MASTER_DATA_API_DB_";c=await asyncpg.connect(host=os.environ[p+"HOSTNAME"],port=int(os.environ[p+"PORT"]),database=os.environ[p+"DBNAME"],user=os.environ[p+"USERNAME"],password=os.environ[p+"PASSWORD"])\n rows=await c.fetch("SELECT s.level_value_mnemonic AS state,count(l.level_value_id) AS n FROM g2p_geo_level_values s LEFT JOIN g2p_geo_level_values l ON l.parent_level_value_id=s.level_value_id AND l.level_id='lga' WHERE s.level_id='state' GROUP BY s.level_value_mnemonic ORDER BY s.level_value_mnemonic");print(json.dumps({r['state']:r['n'] for r in rows}));await c.close()\nasyncio.run(main())\n'''
r=subprocess.run(['kubectl','-n','nigeria','exec','-i','deploy/commons-services-master-data-api','--','python','-'],input=script,text=True,capture_output=True,check=True);actual=json.loads(r.stdout);assert dict(expected)==actual,(expected,actual);print('PASS: 774 LGAs / area councils; all 37 state totals match source')
